-- HACKMYSURU 1.0 | TEAM DATABASE | Safe shared initialization\n-- This TEAM copy does not DROP the database.\n-- It creates the database if it does not already exist, then creates/populates the project tables.\n\n-- HACKMYSURU 1.0 | ROUTING DATABASE | Revised 18 September 2026

-- Current routing uses CURRENT_OPERATIONAL local bodies.

-- GMCC is preserved as NOTIFIED_NOT_OPERATIONAL because the latest status evidence found says formation was delayed/status quo remained.

CREATE DATABASE IF NOT EXISTS hackmysuru_civic_routing CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

USE hackmysuru_civic_routing;

SET FOREIGN_KEY_CHECKS=0;



CREATE TABLE source_documents (
 source_id INT PRIMARY KEY AUTO_INCREMENT, title VARCHAR(255) NOT NULL, publisher VARCHAR(255) NOT NULL,
 source_date DATE NULL, url VARCHAR(1000) NOT NULL,
 source_type ENUM('OFFICIAL','GOVT_REPORT','NEWS','REFERENCE') NOT NULL, notes TEXT);

CREATE TABLE authority_types (
 authority_type_id INT PRIMARY KEY AUTO_INCREMENT, code VARCHAR(50) UNIQUE NOT NULL, name VARCHAR(150) NOT NULL);

CREATE TABLE authorities (
 authority_id INT PRIMARY KEY, authority_type_id INT NOT NULL, name VARCHAR(255) NOT NULL, short_name VARCHAR(100),
 status ENUM('CURRENT_OPERATIONAL','NOTIFIED_NOT_OPERATIONAL','PROPOSAL_ONLY','LEGACY') NOT NULL,
 notified_date DATE NULL, address VARCHAR(500), phone VARCHAR(100), email VARCHAR(255), source_id INT NULL, notes TEXT,
 FOREIGN KEY(authority_type_id) REFERENCES authority_types(authority_type_id),
 FOREIGN KEY(source_id) REFERENCES source_documents(source_id));

CREATE TABLE authority_status_history (
 status_history_id BIGINT PRIMARY KEY AUTO_INCREMENT, authority_id INT NOT NULL,
 status_code ENUM('CURRENT_OPERATIONAL','NOTIFIED_NOT_OPERATIONAL','PROPOSAL_ONLY','LEGACY') NOT NULL,
 valid_from DATE NULL, valid_until DATE NULL, as_of_date DATE NOT NULL, source_id INT NULL, notes TEXT,
 FOREIGN KEY(authority_id) REFERENCES authorities(authority_id), FOREIGN KEY(source_id) REFERENCES source_documents(source_id));

CREATE TABLE departments (
 department_id INT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(150) UNIQUE NOT NULL, description TEXT);

CREATE TABLE authority_departments (
 authority_department_id INT PRIMARY KEY AUTO_INCREMENT, authority_id INT NOT NULL, department_id INT NOT NULL,
 operational_status ENUM('CURRENT','FUTURE','VERIFY') NOT NULL DEFAULT 'CURRENT',
 valid_from DATE NULL, valid_until DATE NULL, source_id INT NULL,
 UNIQUE(authority_id,department_id,operational_status),
 FOREIGN KEY(authority_id) REFERENCES authorities(authority_id), FOREIGN KEY(department_id) REFERENCES departments(department_id),
 FOREIGN KEY(source_id) REFERENCES source_documents(source_id));

CREATE TABLE zones (
 zone_id INT PRIMARY KEY AUTO_INCREMENT, authority_id INT NOT NULL, zone_number INT NOT NULL, zone_name VARCHAR(150),
 status ENUM('CURRENT','HISTORICAL','PENDING_VERIFICATION') NOT NULL DEFAULT 'CURRENT', source_id INT NULL,
 UNIQUE(authority_id,zone_number), FOREIGN KEY(authority_id) REFERENCES authorities(authority_id),
 FOREIGN KEY(source_id) REFERENCES source_documents(source_id));

CREATE TABLE wards (
 ward_id INT PRIMARY KEY AUTO_INCREMENT, authority_id INT NOT NULL, ward_number INT NOT NULL, ward_name VARCHAR(255) NOT NULL,
 zone_id INT NULL, status ENUM('CURRENT','HISTORICAL','PENDING_VERIFICATION') NOT NULL DEFAULT 'CURRENT', source_id INT NULL,
 UNIQUE(authority_id,ward_number), FOREIGN KEY(authority_id) REFERENCES authorities(authority_id),
 FOREIGN KEY(zone_id) REFERENCES zones(zone_id), FOREIGN KEY(source_id) REFERENCES source_documents(source_id));

CREATE TABLE localities (
 locality_id INT PRIMARY KEY AUTO_INCREMENT, locality_name VARCHAR(255) NOT NULL, parent_local_body VARCHAR(255),
 locality_type ENUM('WARD','VILLAGE','TOWN','GP_AREA','TP_AREA','CMC_AREA','OTHER') NOT NULL,
 area_sq_km DECIMAL(10,3) NULL, pincode VARCHAR(10) NULL, source_id INT NULL,
 UNIQUE(locality_name,parent_local_body), FOREIGN KEY(source_id) REFERENCES source_documents(source_id));

CREATE TABLE locality_aliases (
 alias_id INT PRIMARY KEY AUTO_INCREMENT, locality_id INT NOT NULL, alias_name VARCHAR(255) NOT NULL, source_id INT NULL,
 UNIQUE(locality_id,alias_name), FOREIGN KEY(locality_id) REFERENCES localities(locality_id),
 FOREIGN KEY(source_id) REFERENCES source_documents(source_id));

CREATE TABLE jurisdiction_history (
 jurisdiction_id BIGINT PRIMARY KEY AUTO_INCREMENT, locality_id INT NOT NULL, authority_id INT NOT NULL,
 ward_id INT NULL, zone_id INT NULL,
 role_code ENUM('CURRENT_OPERATIONAL','NOTIFIED_FUTURE','HISTORICAL','DISPUTED') NOT NULL,
 valid_from DATE NULL, valid_until DATE NULL, as_of_date DATE NOT NULL, source_id INT NULL,
 change_reason VARCHAR(1000), notes TEXT,
 FOREIGN KEY(locality_id) REFERENCES localities(locality_id), FOREIGN KEY(authority_id) REFERENCES authorities(authority_id),
 FOREIGN KEY(ward_id) REFERENCES wards(ward_id), FOREIGN KEY(zone_id) REFERENCES zones(zone_id),
 FOREIGN KEY(source_id) REFERENCES source_documents(source_id));

CREATE TABLE expansion_components (
 component_id BIGINT PRIMARY KEY AUTO_INCREMENT, future_authority_id INT NOT NULL, source_id INT NOT NULL,
 component_type ENUM('MCC_65_WARDS','CMC','TP','GP_ENTIRE','GP_SELECTED_VILLAGE') NOT NULL,
 source_body_name VARCHAR(255) NOT NULL, locality_id INT NULL,
 inclusion_status ENUM('NOTIFIED','PROPOSAL_ONLY','DISPUTED') NOT NULL, source_date DATE NULL, notes TEXT,
 FOREIGN KEY(future_authority_id) REFERENCES authorities(authority_id), FOREIGN KEY(source_id) REFERENCES source_documents(source_id),
 FOREIGN KEY(locality_id) REFERENCES localities(locality_id));

CREATE TABLE issue_categories (
 issue_category_id INT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(150) UNIQUE NOT NULL, department_id INT NOT NULL,
 keywords VARCHAR(1000), priority ENUM('LOW','MEDIUM','HIGH','CRITICAL') NOT NULL DEFAULT 'MEDIUM', source_id INT NULL,
 FOREIGN KEY(department_id) REFERENCES departments(department_id), FOREIGN KEY(source_id) REFERENCES source_documents(source_id));

CREATE TABLE routing_rules (
 rule_id BIGINT PRIMARY KEY AUTO_INCREMENT, issue_category_id INT NOT NULL, authority_id INT NOT NULL, department_id INT NOT NULL,
 locality_id INT NULL, ward_id INT NULL, zone_id INT NULL,
 routing_scope ENUM('CURRENT_OPERATIONAL','NOTIFIED_FUTURE','HISTORICAL','FALLBACK') NOT NULL,
 valid_from DATE NULL, valid_until DATE NULL,
 rule_status ENUM('ACTIVE','HISTORICAL','PENDING_VERIFICATION') NOT NULL,
 confidence DECIMAL(5,4) NOT NULL DEFAULT 0.8000, explanation_template VARCHAR(1000), source_id INT NULL,
 FOREIGN KEY(issue_category_id) REFERENCES issue_categories(issue_category_id), FOREIGN KEY(authority_id) REFERENCES authorities(authority_id),
 FOREIGN KEY(department_id) REFERENCES departments(department_id), FOREIGN KEY(locality_id) REFERENCES localities(locality_id),
 FOREIGN KEY(ward_id) REFERENCES wards(ward_id), FOREIGN KEY(zone_id) REFERENCES zones(zone_id),
 FOREIGN KEY(source_id) REFERENCES source_documents(source_id));

CREATE TABLE service_contacts (
 contact_id INT PRIMARY KEY AUTO_INCREMENT, authority_id INT NOT NULL, department_id INT NULL,
 contact_type ENUM('OFFICE','HELPLINE','EMAIL','WEBSITE','ESCALATION') NOT NULL, contact_name VARCHAR(255),
 phone VARCHAR(100), email VARCHAR(255), url VARCHAR(1000), valid_from DATE NULL, valid_until DATE NULL,
 source_id INT NULL, notes TEXT, FOREIGN KEY(authority_id) REFERENCES authorities(authority_id),
 FOREIGN KEY(department_id) REFERENCES departments(department_id), FOREIGN KEY(source_id) REFERENCES source_documents(source_id));

CREATE TABLE officers (
 officer_id INT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(255) NOT NULL, designation VARCHAR(255) NOT NULL,
 department_id INT NULL, authority_id INT NULL, zone_id INT NULL, valid_from DATE NULL, valid_until DATE NULL,
 record_status ENUM('CURRENT','HISTORICAL','VERIFY_BEFORE_USE') NOT NULL DEFAULT 'VERIFY_BEFORE_USE',
 source_id INT NULL, notes TEXT, FOREIGN KEY(department_id) REFERENCES departments(department_id),
 FOREIGN KEY(authority_id) REFERENCES authorities(authority_id), FOREIGN KEY(zone_id) REFERENCES zones(zone_id),
 FOREIGN KEY(source_id) REFERENCES source_documents(source_id));

CREATE TABLE complaints (
 complaint_id BIGINT PRIMARY KEY AUTO_INCREMENT, description TEXT NOT NULL, issue_category_id INT NULL,
 latitude DECIMAL(10,7) NULL, longitude DECIMAL(10,7) NULL, address_text VARCHAR(1000),
 locality_id INT NULL, ward_id INT NULL, zone_id INT NULL, authority_id INT NULL, department_id INT NULL,
 routing_confidence DECIMAL(5,4) NULL, routing_reason TEXT,
 routing_scope ENUM('CURRENT_OPERATIONAL','NOTIFIED_FUTURE','UNKNOWN') NOT NULL DEFAULT 'UNKNOWN',
 status ENUM('NEW','ROUTED','ACKNOWLEDGED','IN_PROGRESS','RESOLVED','REJECTED','ESCALATED') NOT NULL DEFAULT 'NEW',
 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 FOREIGN KEY(issue_category_id) REFERENCES issue_categories(issue_category_id), FOREIGN KEY(locality_id) REFERENCES localities(locality_id),
 FOREIGN KEY(ward_id) REFERENCES wards(ward_id), FOREIGN KEY(zone_id) REFERENCES zones(zone_id),
 FOREIGN KEY(authority_id) REFERENCES authorities(authority_id), FOREIGN KEY(department_id) REFERENCES departments(department_id));

CREATE TABLE complaint_status_history (
 status_history_id BIGINT PRIMARY KEY AUTO_INCREMENT, complaint_id BIGINT NOT NULL, old_status VARCHAR(50),
 new_status VARCHAR(50) NOT NULL, changed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, changed_by VARCHAR(255), notes TEXT,
 FOREIGN KEY(complaint_id) REFERENCES complaints(complaint_id));

CREATE TABLE routing_logs (
 routing_log_id BIGINT PRIMARY KEY AUTO_INCREMENT, complaint_id BIGINT NOT NULL, evaluated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 detected_locality VARCHAR(255), detected_ward VARCHAR(255), selected_authority VARCHAR(255), selected_department VARCHAR(255),
 rule_id BIGINT NULL, confidence DECIMAL(5,4) NULL, reason TEXT, jurisdiction_version VARCHAR(100),
 FOREIGN KEY(complaint_id) REFERENCES complaints(complaint_id), FOREIGN KEY(rule_id) REFERENCES routing_rules(rule_id));

SET FOREIGN_KEY_CHECKS=1;



