CREATE INDEX idx_locality_name ON localities(locality_name);
CREATE INDEX idx_locality_parent ON localities(parent_local_body);
CREATE INDEX idx_alias_name ON locality_aliases(alias_name);
CREATE INDEX idx_jurisdiction_lookup ON jurisdiction_history(locality_id,role_code,as_of_date);
CREATE INDEX idx_routing_issue ON routing_rules(issue_category_id,routing_scope,rule_status);
CREATE INDEX idx_complaint_status ON complaints(status);


CREATE OR REPLACE VIEW v_current_locality_routing AS
SELECT j.locality_id,l.locality_name,l.parent_local_body,j.authority_id,a.name authority_name,a.short_name,j.role_code
FROM jurisdiction_history j JOIN localities l ON l.locality_id=j.locality_id
JOIN authorities a ON a.authority_id=j.authority_id
WHERE j.role_code='CURRENT_OPERATIONAL';

CREATE OR REPLACE VIEW v_current_issue_routing AS
SELECT r.rule_id,i.name issue_name,r.authority_id,a.name authority_name,
r.department_id,d.name department_name,r.confidence,r.explanation_template
FROM routing_rules r
JOIN issue_categories i ON i.issue_category_id=r.issue_category_id
JOIN authorities a ON a.authority_id=r.authority_id
JOIN departments d ON d.department_id=r.department_id
WHERE r.routing_scope='CURRENT_OPERATIONAL' AND r.rule_status='ACTIVE';

